main.script:
document.addEventListener("DOMContentLoaded", function() {
    const btnGrid = document.getElementById('btn-view-grid');
    const btnList = document.getElementById('btn-view-list');
    const container = document.getElementById('product-grid-container');

    if(btnGrid && btnList && container) {
        btnGrid.addEventListener('click', () => {
            btnGrid.className = "px-3 py-2 bg-slate-900 text-white transition-colors flex items-center justify-center";
            btnList.className = "px-3 py-2 bg-slate-100 text-slate-700 hover:bg-slate-200 transition-colors flex items-center justify-center";

            container.className = "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-space-md";

            const cards = container.querySelectorAll('.product-card');
            const images = container.querySelectorAll('.product-image');

            cards.forEach(card => {
                card.classList.remove('flex-row', 'sm:flex-row', 'items-center', 'gap-4');
                card.classList.add('flex-col');
            });

            images.forEach(img => {
                img.classList.remove('w-1/3', 'shrink-0', 'h-full', 'min-h-[200px]', 'rounded-l-lg', 'rounded-tr-none');
                img.classList.add('w-full', 'h-48');
            });
        });

        btnList.addEventListener('click', () => {
            btnList.className = "px-3 py-2 bg-slate-900 text-white transition-colors flex items-center justify-center";
            btnGrid.className = "px-3 py-2 bg-slate-100 text-slate-700 hover:bg-slate-200 transition-colors flex items-center justify-center";

            container.className = "grid grid-cols-1 gap-space-md";

            const cards = container.querySelectorAll('.product-card');
            const images = container.querySelectorAll('.product-image');

            cards.forEach(card => {
                card.classList.remove('flex-col');
                card.classList.add('flex-row', 'sm:flex-row', 'items-center', 'gap-4');
            });

            images.forEach(img => {
                img.classList.remove('w-full', 'h-48');
                img.classList.add('w-1/3', 'shrink-0', 'h-full', 'min-h-[200px]', 'rounded-l-lg', 'rounded-tr-none');
            });
        });
    }
});
